WITH source_forms(codigo, titulo, descricao, payload) AS (
VALUES
  ('risco_inundacao_v1', 'Risco de Inundação, Alagamento e Enxurrada', 'Vistoria visual de campo para avaliar inundação, alagamento e enxurrada, seus efeitos sobre pessoas, imóveis, vias e equipamentos públicos.', '{"id":"risco_inundacao_v1","titulo":"Risco de Inundação, Alagamento e Enxurrada","versao":1,"ativo":true,"featureCode":"inspection_standard","tipoCalculo":"soma_total","observacaoCondicionalRisco":{"ativo":true,"pesoMinimo":0.3,"titulo":"Evidência técnica da condição hídrica","descricao":"Descreva a evidência observada, a área exposta e a medida recomendada."},"descricao":"Vistoria visual de campo para avaliar inundação, alagamento e enxurrada, seus efeitos sobre pessoas, imóveis, vias e equipamentos públicos.","classificacao":{"limites":[{"max":2,"nivel":"r1","label":"R1 — BAIXO — Sem ameaça imediata identificada","cor":"verde"},{"max":3.9,"nivel":"r2","label":"R2 — MÉDIO — Monitoramento e medidas preventivas","cor":"amarelo"},{"max":6.9,"nivel":"r3","label":"R3 — ALTO — Intervenção e restrição preventiva necessárias","cor":"laranja"},{"max":10,"nivel":"r4","label":"R4 — CRÍTICO — Evacuação, isolamento ou interdição quando aplicável","cor":"vermelho"}]},"fases":[{"id":"inundacao_caracterizacao","titulo":"Caracterização da ocorrência","instrucao":"Registre a condição da água e os sinais observados no local. Considere a situação no momento da vistoria e as marcas recentes.","perguntas":[{"id":"inundacao_foto_geral","texto":"Foto geral da área vistoriada","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"inundacao_q1","texto":"Qual condição hídrica foi identificada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_evidencia","texto":"Sem evidência de água ou escoamento relevante","descricao":"Não foram observadas marcas, acúmulo ou correnteza com potencial de dano.","pesoRisco":0},{"id":"alagamento_lento","texto":"Alagamento lento ou acúmulo localizado","descricao":"Água acumulada sem correnteza significativa e com baixa energia.","pesoRisco":0.3},{"id":"inundacao_progressiva","texto":"Inundação progressiva","descricao":"Elevação de água em área baixa, margem ou curso d''água próximo.","pesoRisco":0.6},{"id":"enxurrada_correnteza","texto":"Enxurrada ou correnteza forte","descricao":"Escoamento rápido, com energia suficiente para arrastar pessoas, veículos ou materiais.","pesoRisco":1}]},{"id":"inundacao_q2","texto":"Qual a maior altura ou marca de água observada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_marca","texto":"Sem marca ou lâmina de água","descricao":"Não há evidência de altura significativa.","pesoRisco":0},{"id":"lamina_baixa","texto":"Até 30 cm","descricao":"Lâmina baixa, sem atingir pontos sensíveis da edificação ou via.","pesoRisco":0.3},{"id":"lamina_media","texto":"Entre 30 cm e 1 m","descricao":"Água capaz de atingir acessos, instalações baixas ou circulação local.","pesoRisco":0.6},{"id":"lamina_alta","texto":"Acima de 1 m ou sem limite visível","descricao":"Altura elevada, com potencial de atingir pessoas, imóveis e estruturas.","pesoRisco":1}]},{"id":"inundacao_q3","texto":"Como está o escoamento da água?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"escoamento_normal","texto":"Escoamento normal","descricao":"Drenagem funcionando sem sinais de transbordamento.","pesoRisco":0},{"id":"escoamento_lento","texto":"Escoamento lento","descricao":"Há retenção ou drenagem insuficiente, mas sem transbordamento relevante.","pesoRisco":0.3},{"id":"drenagem_insuficiente","texto":"Drenagem insuficiente","descricao":"A água permanece ou retorna para a área vistoriada.","pesoRisco":0.6},{"id":"drenagem_obstruida","texto":"Drenagem obstruída ou transbordando","descricao":"Bueiro, galeria, canal ou curso d''água não comporta o escoamento observado.","pesoRisco":1}]},{"id":"inundacao_q4","texto":"Qual a característica do terreno ou área de escoamento?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"area_elevada","texto":"Área elevada ou fora do caminho da água","descricao":"O local não apresenta depressão ou conexão evidente com o escoamento.","pesoRisco":0},{"id":"baixo_localizado","texto":"Ponto baixo localizado","descricao":"A área recebe água de trechos próximos ou apresenta pequena depressão.","pesoRisco":0.3},{"id":"varzea_margem","texto":"Várzea, margem ou área naturalmente inundável","descricao":"O local está próximo de curso d''água ou em área de extravasamento.","pesoRisco":0.6},{"id":"canal_passagem","texto":"Canal de passagem ou caminho concentrado de água","descricao":"A água se concentra com energia e atravessa o local vistoriado.","pesoRisco":1}]},{"id":"inundacao_altura_agua_m","texto":"Altura aproximada da água em metros","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"m","valorMinimo":0,"valorMaximo":10,"obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: 0,45","mostrarQuando":{"perguntaId":"inundacao_q2","respostaIds":["lamina_baixa","lamina_media","lamina_alta"]},"opcoes":[]}]},{"id":"inundacao_exposicao","titulo":"Exposição de pessoas e estruturas","instrucao":"Avalie quem ou o que pode ser atingido pela água, incluindo rotas de acesso, residências e equipamentos públicos.","perguntas":[{"id":"inundacao_q5","texto":"Há erosão, solapamento ou perda de material causada pela água?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_erosao","texto":"Sem erosão aparente","descricao":"Margens, solo e pavimento sem perda relevante de material.","pesoRisco":0},{"id":"erosao_leve","texto":"Erosão leve ou localizada","descricao":"Pequena perda de solo sem ameaça imediata a estruturas.","pesoRisco":0.3},{"id":"erosao_visivel","texto":"Erosão visível próxima a estrutura","descricao":"A perda de material se aproxima de imóvel, via, muro ou fundação.","pesoRisco":0.6},{"id":"solapamento_ativo","texto":"Solapamento ativo ou perda de apoio","descricao":"A água remove material e pode comprometer a estabilidade do local.","pesoRisco":1}]},{"id":"inundacao_q6","texto":"Qual a exposição de pessoas no local ou entorno?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_pessoas","texto":"Sem pessoas ou ocupação próxima","descricao":"Não há uso frequente ou pessoas potencialmente atingíveis.","pesoRisco":0},{"id":"ocupacao_eventual","texto":"Ocupação eventual","descricao":"Há circulação ocasional, sem residência ou atividade contínua.","pesoRisco":0.3},{"id":"residencias_proximas","texto":"Residências ou circulação frequente","descricao":"Pessoas podem ser atingidas em moradias, comércio ou via pública.","pesoRisco":0.6},{"id":"vulneraveis_expostos","texto":"Pessoas vulneráveis ou grande concentração exposta","descricao":"Inclui crianças, idosos, pessoas com mobilidade reduzida ou aglomeração.","pesoRisco":1}]},{"id":"inundacao_q7","texto":"Quais danos ou ameaças materiais foram identificados?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_dano","texto":"Sem dano ou ameaça material aparente","descricao":"Não foram observados bens, imóveis ou equipamentos em risco direto.","pesoRisco":0},{"id":"dano_localizado","texto":"Dano localizado e reparável","descricao":"Atinge acabamento, calçada, pequena área de pavimento ou item não essencial.","pesoRisco":0.3},{"id":"imovel_ou_via_atingida","texto":"Imóvel, via ou equipamento atingido","descricao":"Há dano ou perda de funcionamento em uma estrutura ou rota.","pesoRisco":0.6},{"id":"infraestrutura_critica","texto":"Infraestrutura crítica ou múltiplos imóveis ameaçados","descricao":"Atinge ponte, unidade pública, acesso principal, rede essencial ou várias moradias.","pesoRisco":1}]},{"id":"inundacao_q8","texto":"Como está o acesso e a possibilidade de saída segura?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"acesso_livre","texto":"Acesso e saída livres","descricao":"Não há bloqueio ou risco relevante na rota de saída.","pesoRisco":0},{"id":"acesso_atencao","texto":"Acesso com atenção","descricao":"Há pontos molhados ou reduzidos, mas a circulação ainda é possível.","pesoRisco":0.3},{"id":"acesso_restrito","texto":"Acesso parcialmente restrito","descricao":"Veículos ou pessoas precisam de orientação ou rota alternativa.","pesoRisco":0.6},{"id":"acesso_bloqueado","texto":"Acesso bloqueado ou sem saída segura","descricao":"A água, erosão ou danos impedem o deslocamento seguro.","pesoRisco":1}]},{"id":"inundacao_acao_imediata","texto":"Medida imediata adotada ou recomendada","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: isolar a via, orientar moradores e acionar equipe de trânsito.","mostrarQuando":{"perguntaId":"inundacao_q8","respostaIds":["acesso_restrito","acesso_bloqueado"]},"opcoes":[]}]},{"id":"inundacao_evolucao","titulo":"Evolução e medidas preventivas","instrucao":"Registre a recorrência, a capacidade de proteção existente e as providências indicadas para o local.","perguntas":[{"id":"inundacao_q9","texto":"Qual a recorrência ou tendência observada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_historico","texto":"Sem histórico conhecido","descricao":"Não há relato ou evidência de repetição no local.","pesoRisco":0},{"id":"evento_isolado","texto":"Evento isolado","descricao":"Ocorreu uma vez ou em situação excepcional sem sinais de repetição.","pesoRisco":0.3},{"id":"recorrente","texto":"Ocorrência recorrente","descricao":"Moradores ou registros indicam repetição em períodos de chuva.","pesoRisco":0.6},{"id":"agravamento","texto":"Recorrência com agravamento","descricao":"A frequência, altura, velocidade ou área atingida está aumentando.","pesoRisco":1}]},{"id":"inundacao_q10","texto":"Como estão as medidas de proteção e prevenção?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"protecao_adequada","texto":"Proteção adequada","descricao":"Drenagem, orientação e rotas de saída atendem à condição observada.","pesoRisco":0},{"id":"protecao_parcial","texto":"Proteção parcial","descricao":"Existem medidas, mas requerem manutenção ou complementação.","pesoRisco":0.3},{"id":"protecao_insuficiente","texto":"Proteção insuficiente","descricao":"As medidas atuais não controlam a ameaça identificada.","pesoRisco":0.6},{"id":"sem_protecao","texto":"Sem proteção ou com falha grave","descricao":"Não há medida efetiva ou a proteção existente está comprometida.","pesoRisco":1}]},{"id":"inundacao_foto_marca_agua","texto":"Foto de marca de água, erosão ou dano","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"inundacao_observacoes","texto":"Observações técnicas adicionais","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Registre referências, relatos, pontos de medição e recomendações.","opcoes":[]}]}]}'::jsonb),
  ('risco_incendio_vegetacao_v1', 'Risco de Incêndio em Vegetação', 'Vistoria preventiva ou emergencial de áreas com vegetação seca, fumaça ou fogo, avaliando propagação, exposição de pessoas e acesso para resposta.', '{"id":"risco_incendio_vegetacao_v1","titulo":"Risco de Incêndio em Vegetação","versao":1,"ativo":true,"featureCode":"inspection_standard","tipoCalculo":"soma_total","observacaoCondicionalRisco":{"ativo":true,"pesoMinimo":0.3,"titulo":"Evidência técnica do risco de incêndio","descricao":"Descreva o material combustível, a área exposta, a direção provável de propagação e a medida recomendada."},"descricao":"Vistoria preventiva ou emergencial de áreas com vegetação seca, fumaça ou fogo, avaliando propagação, exposição de pessoas e acesso para resposta.","classificacao":{"limites":[{"max":2,"nivel":"r1","label":"R1 — BAIXO — Condição controlada e sem ameaça imediata","cor":"verde"},{"max":3.9,"nivel":"r2","label":"R2 — MÉDIO — Prevenção e monitoramento recomendados","cor":"amarelo"},{"max":6.9,"nivel":"r3","label":"R3 — ALTO — Acionamento e controle preventivo necessários","cor":"laranja"},{"max":10,"nivel":"r4","label":"R4 — CRÍTICO — Propagação ou exposição grave; acionar resposta imediata","cor":"vermelho"}]},"fases":[{"id":"incendio_caracterizacao","titulo":"Caracterização do fogo e da área","instrucao":"Não se aproxime de fogo ativo. Registre somente condições observáveis com segurança e acione os órgãos responsáveis quando houver fumaça ou chamas.","perguntas":[{"id":"incendio_foto_geral","texto":"Foto geral da área de vegetação","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"incendio_q1","texto":"Qual situação foi identificada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_fogo","texto":"Sem fumaça ou fogo aparente","descricao":"A vistoria identifica apenas condição preventiva sem sinais de combustão.","pesoRisco":0},{"id":"vegetacao_suscetivel","texto":"Vegetação suscetível, sem fogo","descricao":"Há material seco e condição favorável, mas sem fumaça ou chama.","pesoRisco":0.3},{"id":"fumaca_ou_foco","texto":"Fumaça ou foco localizado","descricao":"Há sinal de combustão, mas não foi observada propagação ampla.","pesoRisco":0.6},{"id":"fogo_propagando","texto":"Fogo ativo ou em propagação","descricao":"Chamas, frente de fogo ou propagação visível na área.","pesoRisco":1}]},{"id":"incendio_q2","texto":"Qual o grau de ressecamento da vegetação?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"vegetacao_umida","texto":"Vegetação úmida ou verde","descricao":"Baixa disponibilidade imediata de material combustível seco.","pesoRisco":0},{"id":"secamento_local","texto":"Secamento localizado","descricao":"Há trechos secos, mas a continuidade do material é limitada.","pesoRisco":0.3},{"id":"vegetacao_seca","texto":"Vegetação predominantemente seca","descricao":"Material combustível seco em grande parte da área.","pesoRisco":0.6},{"id":"material_extremamente_seco","texto":"Material extremamente seco","descricao":"Vegetação seca, leve e contínua, com alta facilidade de ignição.","pesoRisco":1}]},{"id":"incendio_q3","texto":"Qual a quantidade de material combustível acumulado?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"baixo","texto":"Baixa","descricao":"Pouca matéria seca, sem continuidade relevante.","pesoRisco":0},{"id":"moderado","texto":"Moderada","descricao":"Folhas, capim ou galhos secos em pontos delimitados.","pesoRisco":0.3},{"id":"alto","texto":"Alta","descricao":"Material acumulado ou contínuo em boa parte da área.","pesoRisco":0.6},{"id":"muito_alto","texto":"Muito alta","descricao":"Mato alto, resíduos, galhos ou material contínuo junto a áreas expostas.","pesoRisco":1}]},{"id":"incendio_q4","texto":"Qual a possibilidade de propagação?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"propagacao_limitada","texto":"Propagação limitada","descricao":"Área pequena, sem continuidade e sem vento relevante observado.","pesoRisco":0},{"id":"propagacao_direcionada","texto":"Propagação direcionada","descricao":"A continuidade do material ou a topografia pode conduzir o fogo.","pesoRisco":0.3},{"id":"propagacao_facilitada","texto":"Propagação facilitada","descricao":"Vento, declive ou material contínuo favorecem o avanço.","pesoRisco":0.6},{"id":"propagacao_rapida","texto":"Propagação rápida ou sem controle","descricao":"Fogo avança em direção a áreas ocupadas ou não pode ser contido localmente.","pesoRisco":1}]},{"id":"incendio_foto_fumaca_fogo","texto":"Foto segura da fumaça, foco ou área afetada","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"incendio_area_ha","texto":"Área aproximada afetada em hectares","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"ha","valorMinimo":0,"valorMaximo":100000,"obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: 2,5","opcoes":[]}]},{"id":"incendio_exposicao","titulo":"Exposição e capacidade de resposta","instrucao":"Avalie o que pode ser atingido e se as equipes conseguem acessar a área sem se expor ao fogo.","perguntas":[{"id":"incendio_q5","texto":"Qual a proximidade de imóveis ou instalações sensíveis?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_exposicao","texto":"Sem imóvel ou instalação próxima","descricao":"A área não apresenta alvo vulnerável no entorno imediato.","pesoRisco":0},{"id":"alvo_distante","texto":"Alvo distante","descricao":"Há imóveis ou instalações, mas fora da direção provável de propagação.","pesoRisco":0.3},{"id":"imoveis_proximos","texto":"Imóveis ou instalações próximas","descricao":"O fogo pode alcançar residências, comércio, escola ou unidade pública.","pesoRisco":0.6},{"id":"alvo_ameacado","texto":"Alvo diretamente ameaçado","descricao":"Fogo, fumaça ou calor já atingem ou se aproximam de área ocupada.","pesoRisco":1}]},{"id":"incendio_q6","texto":"Há pessoas ou população vulnerável exposta?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_pessoas","texto":"Sem pessoas expostas","descricao":"Não há ocupação ou circulação próxima observada.","pesoRisco":0},{"id":"circulacao_eventual","texto":"Circulação eventual","descricao":"Há passagem ocasional, sem concentração de pessoas.","pesoRisco":0.3},{"id":"ocupacao_frequente","texto":"Ocupação frequente","descricao":"Pessoas moram, trabalham ou circulam próximas à área.","pesoRisco":0.6},{"id":"vulneraveis_expostos","texto":"Pessoas vulneráveis expostas","descricao":"Inclui crianças, idosos, pessoas com mobilidade reduzida ou aglomeração.","pesoRisco":1}]},{"id":"incendio_q7","texto":"Como está o acesso para equipes e veículos?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"acesso_bom","texto":"Acesso bom","descricao":"Há rota livre e segura para aproximação das equipes.","pesoRisco":0},{"id":"acesso_limitado","texto":"Acesso limitado","descricao":"Aproximação depende de veículo menor, orientação ou rota alternativa.","pesoRisco":0.3},{"id":"acesso_dificil","texto":"Acesso difícil","descricao":"Topografia, vegetação ou via impedem parte da resposta.","pesoRisco":0.6},{"id":"sem_acesso_seguro","texto":"Sem acesso seguro","descricao":"A aproximação expõe equipes ou não permite resposta terrestre adequada.","pesoRisco":1}]},{"id":"incendio_q8","texto":"Há água, equipamentos ou apoio disponíveis para a resposta?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"recursos_disponiveis","texto":"Recursos disponíveis","descricao":"Há fonte de água, acesso e equipe ou apoio compatível com a situação.","pesoRisco":0},{"id":"recursos_parciais","texto":"Recursos parciais","descricao":"Existe parte dos recursos, mas é necessário apoio complementar.","pesoRisco":0.3},{"id":"recursos_insuficientes","texto":"Recursos insuficientes","descricao":"A resposta local não cobre a extensão ou o avanço provável.","pesoRisco":0.6},{"id":"sem_recursos","texto":"Sem recursos ou apoio imediato","descricao":"Não há condição local de resposta segura ou suficiente.","pesoRisco":1}]}]},{"id":"incendio_preventivo","titulo":"Prevenção e providências","instrucao":"Registre as condições de prevenção e a providência necessária. O combate a incêndio deve ser realizado por equipes habilitadas.","perguntas":[{"id":"incendio_q9","texto":"Como estão os aceiros e a manutenção da área?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"manutencao_adequada","texto":"Manutenção adequada","descricao":"Aceiros, limpeza e controle da vegetação reduzem a continuidade do combustível.","pesoRisco":0},{"id":"manutencao_parcial","texto":"Manutenção parcial","descricao":"Há proteção em parte da área, mas existem trechos sem cuidado.","pesoRisco":0.3},{"id":"sem_aceiro_suficiente","texto":"Aceiro insuficiente ou limpeza inadequada","descricao":"A continuidade da vegetação aumenta a chance de propagação.","pesoRisco":0.6},{"id":"area_sem_controle","texto":"Área sem controle preventivo","descricao":"Não há aceiro, limpeza ou medida capaz de reduzir o risco identificado.","pesoRisco":1}]},{"id":"incendio_q10","texto":"Qual a situação da providência imediata?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"monitorar","texto":"Monitorar e orientar","descricao":"Risco preventivo sem necessidade de isolamento imediato.","pesoRisco":0},{"id":"limpar_area","texto":"Solicitar limpeza ou aceiro","descricao":"A prevenção depende de manutenção e redução do material combustível.","pesoRisco":0.3},{"id":"isolar_area","texto":"Isolar ou restringir acesso","descricao":"A área precisa de sinalização, isolamento ou acionamento de equipe.","pesoRisco":0.6},{"id":"acionar_emergencia","texto":"Acionar resposta de emergência","descricao":"Há fogo, fumaça ou ameaça grave; acione Corpo de Bombeiros e Defesa Civil.","pesoRisco":1}]},{"id":"incendio_acao_imediata","texto":"Descreva o acionamento ou a medida adotada","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: Corpo de Bombeiros acionado; área sinalizada; moradores orientados a deixar o local.","mostrarQuando":{"perguntaId":"incendio_q1","respostaIds":["fumaca_ou_foco","fogo_propagando"]},"opcoes":[]},{"id":"incendio_observacoes","texto":"Observações técnicas adicionais","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Registre direção do vento, limites da área, relatos e recomendações.","opcoes":[]}]}]}'::jsonb),
  ('inspecao_ponte_passarela_v1', 'Inspeção Visual de Ponte e Passarela', 'Inspeção visual preliminar de pontes, pontilhões e passarelas para identificar danos, risco de uso e necessidade de avaliação especializada.', '{"id":"inspecao_ponte_passarela_v1","titulo":"Inspeção Visual de Ponte e Passarela","versao":1,"ativo":true,"featureCode":"inspection_standard","tipoCalculo":"soma_total","observacaoCondicionalRisco":{"ativo":true,"pesoMinimo":0.3,"titulo":"Evidência técnica da estrutura","descricao":"Descreva o elemento afetado, a localização do dano, a extensão aparente e a providência recomendada."},"descricao":"Inspeção visual preliminar de pontes, pontilhões e passarelas para identificar danos, risco de uso e necessidade de avaliação especializada.","classificacao":{"limites":[{"max":2,"nivel":"r1","label":"R1 — BAIXO — Condição visual controlada","cor":"verde"},{"max":3.9,"nivel":"r2","label":"R2 — MÉDIO — Monitoramento e manutenção recomendados","cor":"amarelo"},{"max":6.9,"nivel":"r3","label":"R3 — ALTO — Restrição de uso e avaliação técnica necessárias","cor":"laranja"},{"max":10,"nivel":"r4","label":"R4 — CRÍTICO — Isolamento ou interdição imediata quando aplicável","cor":"vermelho"}]},"fases":[{"id":"ponte_identificacao","titulo":"Identificação e segurança de uso","instrucao":"Faça uma inspeção visual sem acessar partes inseguras. Não entre em estrutura instável ou sob risco de queda, colapso, correnteza ou tráfego.","perguntas":[{"id":"ponte_foto_geral","texto":"Foto geral da ponte ou passarela","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"ponte_q1","texto":"Qual a condição geral aparente da estrutura?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"boa","texto":"Boa condição aparente","descricao":"Sem dano relevante visível no conjunto observado.","pesoRisco":0},{"id":"desgaste","texto":"Desgaste ou manutenção pendente","descricao":"Há deterioração superficial ou item de manutenção sem ameaça imediata.","pesoRisco":0.3},{"id":"dano_relevante","texto":"Dano relevante localizado","descricao":"Há elemento danificado que pode afetar o uso ou requer avaliação técnica.","pesoRisco":0.6},{"id":"instabilidade","texto":"Instabilidade, deslocamento ou deformação grave","descricao":"Há sinal de perda de estabilidade, colapso parcial ou condição crítica.","pesoRisco":1}]},{"id":"ponte_q2","texto":"Como está o tabuleiro, piso ou superfície de passagem?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"tabuleiro_integro","texto":"Íntegro e regular","descricao":"Sem buracos, degraus ou deformação relevante.","pesoRisco":0},{"id":"desgaste_superficial","texto":"Desgaste superficial","descricao":"Há desgaste, fissuras leves ou irregularidade sem perda aparente de suporte.","pesoRisco":0.3},{"id":"deformacao_local","texto":"Deformação ou falha localizada","descricao":"A passagem está prejudicada e pode exigir restrição parcial.","pesoRisco":0.6},{"id":"ruptura_tabuleiro","texto":"Ruptura, buraco aberto ou perda de suporte","descricao":"O uso pode causar queda, acidente ou agravamento do dano.","pesoRisco":1}]},{"id":"ponte_q3","texto":"Como estão guarda-corpos, corrimãos e proteção lateral?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"protecao_integra","texto":"Proteção íntegra","descricao":"Guarda-corpos e corrimãos estão presentes e firmes.","pesoRisco":0},{"id":"protecao_desgastada","texto":"Proteção desgastada","descricao":"Há corrosão ou falha leve sem abertura relevante.","pesoRisco":0.3},{"id":"protecao_incompleta","texto":"Proteção incompleta ou solta","descricao":"Há trechos sem proteção ou com risco de queda lateral.","pesoRisco":0.6},{"id":"queda_livre","texto":"Queda livre ou proteção ausente em trecho crítico","descricao":"O uso apresenta risco grave de queda de pessoas ou veículos.","pesoRisco":1}]},{"id":"ponte_comprimento_m","texto":"Comprimento aproximado da estrutura em metros","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"m","valorMinimo":0,"valorMaximo":10000,"obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: 18,5","opcoes":[]}]},{"id":"ponte_elementos_estruturais","titulo":"Elementos estruturais e fundações","instrucao":"Observe pilares, apoios, encontros, lajes e elementos visíveis a partir de local seguro. Registre o ponto exato de cada dano.","perguntas":[{"id":"ponte_q4","texto":"Há trincas, concreto destacado ou armadura exposta?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_dano_concreto","texto":"Sem dano visível","descricao":"Elementos observados sem trinca ou desplacamento relevante.","pesoRisco":0},{"id":"fissura_leve","texto":"Fissuras leves","descricao":"Fissuras finas sem sinal aparente de evolução ou perda de seção.","pesoRisco":0.3},{"id":"trinca_desplacamento","texto":"Trinca, desplacamento ou corrosão localizada","descricao":"Dano relevante que exige registro e avaliação técnica.","pesoRisco":0.6},{"id":"dano_estrutural_grave","texto":"Dano grave em elemento estrutural","descricao":"Perda de seção, armadura exposta extensa, ruptura ou risco de desprendimento.","pesoRisco":1}]},{"id":"ponte_q5","texto":"Foi observada deformação, inclinação ou desalinhamento?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"alinhamento_normal","texto":"Alinhamento normal","descricao":"Não há deformação ou inclinação aparente.","pesoRisco":0},{"id":"desalinhamento_sutil","texto":"Desalinhamento sutil","descricao":"Há alteração visual que deve ser acompanhada.","pesoRisco":0.3},{"id":"deformacao_visivel","texto":"Deformação visível","descricao":"A geometria ou o apoio aparenta alteração relevante.","pesoRisco":0.6},{"id":"inclinacao_grave","texto":"Inclinação ou deslocamento grave","descricao":"Há possível perda de estabilidade ou risco de colapso.","pesoRisco":1}]},{"id":"ponte_q6","texto":"Como estão apoios, pilares, encontros ou fundações visíveis?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"apoio_integro","texto":"Apoios aparentemente íntegros","descricao":"Sem erosão, deslocamento ou dano relevante visível.","pesoRisco":0},{"id":"desgaste_apoio","texto":"Desgaste ou dano superficial","descricao":"Há deterioração sem perda aparente de apoio.","pesoRisco":0.3},{"id":"dano_apoio","texto":"Dano ou deslocamento localizado","descricao":"Há anomalia em apoio, pilar ou encontro que requer avaliação.","pesoRisco":0.6},{"id":"perda_apoio","texto":"Perda de apoio ou instabilidade","descricao":"Há risco de comprometimento do suporte da estrutura.","pesoRisco":1}]},{"id":"ponte_q7","texto":"Há erosão, solapamento ou obstrução junto à água?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"margem_estavel","texto":"Margens e leito estáveis","descricao":"Sem erosão, acúmulo ou impacto aparente nos apoios.","pesoRisco":0},{"id":"erosao_inicial","texto":"Erosão ou acúmulo inicial","descricao":"Há alteração localizada sem exposição de fundação.","pesoRisco":0.3},{"id":"erosao_proxima_apoio","texto":"Erosão próxima a apoio","descricao":"A água remove material na proximidade de pilar, encontro ou margem.","pesoRisco":0.6},{"id":"solapamento_apoio","texto":"Solapamento ou obstrução com risco ao apoio","descricao":"A condição hidráulica pode comprometer a estabilidade ou aumentar esforços.","pesoRisco":1}]},{"id":"ponte_foto_elemento","texto":"Foto do elemento estrutural ou apoio afetado","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]}]},{"id":"ponte_operacao","titulo":"Operação, exposição e providências","instrucao":"Considere o uso atual da estrutura e indique a providência preventiva compatível com o que foi observado.","perguntas":[{"id":"ponte_q8","texto":"Qual a exposição de usuários e tráfego?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"uso_baixo","texto":"Uso baixo ou eventual","descricao":"Poucas pessoas ou veículos utilizam a estrutura.","pesoRisco":0},{"id":"uso_moderado","texto":"Uso moderado","descricao":"Há circulação regular, sem grande concentração.","pesoRisco":0.3},{"id":"uso_intenso","texto":"Uso intenso","descricao":"A estrutura atende fluxo frequente de pessoas ou veículos.","pesoRisco":0.6},{"id":"uso_vulneravel","texto":"Uso intenso com pessoas vulneráveis ou rota essencial","descricao":"A interrupção ou falha pode atingir grande número de pessoas ou acesso essencial.","pesoRisco":1}]},{"id":"ponte_q9","texto":"Qual o nível de restrição necessário neste momento?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_restricao","texto":"Sem restrição imediata","descricao":"Manter uso com monitoramento e manutenção programada.","pesoRisco":0},{"id":"sinalizar","texto":"Sinalizar e monitorar","descricao":"Orientar usuários e acompanhar a evolução do dano.","pesoRisco":0.3},{"id":"restricao_parcial","texto":"Restrição parcial de uso","descricao":"Limitar faixa, peso, velocidade, sentido ou circulação de pedestres.","pesoRisco":0.6},{"id":"interditar","texto":"Isolar ou interditar","descricao":"Impedir o uso até avaliação técnica ou eliminação da condição de risco.","pesoRisco":1}]},{"id":"ponte_q10","texto":"Qual providência deve ser encaminhada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"manutencao_rotina","texto":"Manutenção de rotina","descricao":"Limpeza, pintura, sinalização ou reparo simples programável.","pesoRisco":0},{"id":"avaliacao_tecnica","texto":"Avaliação técnica complementar","descricao":"Encaminhar fotos e registro para profissional ou secretaria responsável.","pesoRisco":0.3},{"id":"intervencao_urgente","texto":"Intervenção urgente","descricao":"Priorizar reparo, escoramento, limpeza hidráulica ou controle de acesso.","pesoRisco":0.6},{"id":"emergencia_interdicao","texto":"Emergência e interdição imediata","descricao":"Acionar responsáveis, sinalizar e impedir o uso até avaliação especializada.","pesoRisco":1}]},{"id":"ponte_acao_imediata","texto":"Descreva a sinalização, isolamento ou encaminhamento realizado","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: acesso lateral isolado e Secretaria de Obras acionada para avaliação.","mostrarQuando":{"perguntaId":"ponte_q9","respostaIds":["restricao_parcial","interditar"]},"opcoes":[]},{"id":"ponte_observacoes","texto":"Observações técnicas adicionais","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Registre localização do dano, material, referências e recomendações.","opcoes":[]}]}]}'::jsonb),
  ('inspecao_bueiro_drenagem_v1', 'Inspeção de Bueiro, Galeria e Drenagem', 'Vistoria visual de bueiros, galerias, sarjetas e dispositivos de drenagem para avaliar obstrução, transbordamento, erosão e ameaça a vias ou imóveis.', '{"id":"inspecao_bueiro_drenagem_v1","titulo":"Inspeção de Bueiro, Galeria e Drenagem","versao":1,"ativo":true,"featureCode":"inspection_standard","tipoCalculo":"soma_total","observacaoCondicionalRisco":{"ativo":true,"pesoMinimo":0.3,"titulo":"Evidência técnica da drenagem","descricao":"Descreva a obstrução, o dano, o caminho da água e a medida recomendada."},"descricao":"Vistoria visual de bueiros, galerias, sarjetas e dispositivos de drenagem para avaliar obstrução, transbordamento, erosão e ameaça a vias ou imóveis.","classificacao":{"limites":[{"max":2,"nivel":"r1","label":"R1 — BAIXO — Drenagem em condição controlada","cor":"verde"},{"max":3.9,"nivel":"r2","label":"R2 — MÉDIO — Limpeza e manutenção recomendadas","cor":"amarelo"},{"max":6.9,"nivel":"r3","label":"R3 — ALTO — Intervenção preventiva urgente necessária","cor":"laranja"},{"max":10,"nivel":"r4","label":"R4 — CRÍTICO — Transbordamento, ruptura ou ameaça grave","cor":"vermelho"}]},"fases":[{"id":"drenagem_identificacao","titulo":"Caracterização do dispositivo","instrucao":"Observe entrada, saída e entorno sem entrar em galerias, bueiros ou locais com água corrente, gases, instabilidade ou risco de soterramento.","perguntas":[{"id":"drenagem_foto_geral","texto":"Foto geral do bueiro, galeria ou trecho de drenagem","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"drenagem_q1","texto":"Qual o estado geral do dispositivo?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"integro","texto":"Íntegro e funcionando","descricao":"Dispositivo sem dano ou alteração relevante aparente.","pesoRisco":0},{"id":"desgaste","texto":"Desgaste ou manutenção pendente","descricao":"Há desgaste, sujeira ou pequena falha sem impacto imediato.","pesoRisco":0.3},{"id":"dano_relevante","texto":"Dano relevante localizado","descricao":"Há falha que reduz o funcionamento ou exige intervenção.","pesoRisco":0.6},{"id":"ruptura","texto":"Ruptura, colapso ou perda de seção","descricao":"O dispositivo não cumpre sua função ou pode agravar o risco no local.","pesoRisco":1}]},{"id":"drenagem_q2","texto":"Qual o nível de obstrução na entrada ou no percurso?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_obstrucao","texto":"Sem obstrução","descricao":"Entrada e percurso aparentam estar livres.","pesoRisco":0},{"id":"obstrucao_leve","texto":"Obstrução leve","descricao":"Há folhas, lixo ou material que não impede o fluxo atual.","pesoRisco":0.3},{"id":"obstrucao_parcial","texto":"Obstrução parcial","descricao":"Parte significativa da seção está bloqueada ou assoreada.","pesoRisco":0.6},{"id":"obstrucao_total","texto":"Obstrução total ou seção colmatada","descricao":"A água não consegue passar ou retorna para a via e imóveis.","pesoRisco":1}]},{"id":"drenagem_q3","texto":"Como está a capacidade de escoamento?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"capacidade_adequada","texto":"Capacidade adequada","descricao":"O fluxo observado passa sem retenção ou transbordamento.","pesoRisco":0},{"id":"capacidade_reduzida","texto":"Capacidade reduzida","descricao":"Há lentidão ou retenção, mas sem transbordamento atual.","pesoRisco":0.3},{"id":"transbordamento_local","texto":"Transbordamento localizado","descricao":"A água ultrapassa o dispositivo em chuva ou fluxo moderado.","pesoRisco":0.6},{"id":"sem_capacidade","texto":"Sem capacidade ou fluxo fora do dispositivo","descricao":"A água não é conduzida e ameaça a via, imóveis ou pessoas.","pesoRisco":1}]},{"id":"drenagem_diametro_m","texto":"Diâmetro ou largura aproximada do dispositivo em metros","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"m","valorMinimo":0,"valorMaximo":100,"obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: 1,2","opcoes":[]}]},{"id":"drenagem_danos","titulo":"Danos, erosão e entorno","instrucao":"Registre os efeitos do escoamento sobre o solo, pavimento, margens e estruturas próximas.","perguntas":[{"id":"drenagem_q4","texto":"Há erosão na entrada, saída ou margem do dispositivo?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_erosao","texto":"Sem erosão aparente","descricao":"Solo, margem e pavimento sem perda relevante de material.","pesoRisco":0},{"id":"erosao_leve","texto":"Erosão leve","descricao":"Pequena perda de solo sem ameaça imediata.","pesoRisco":0.3},{"id":"erosao_proxima","texto":"Erosão próxima à via ou estrutura","descricao":"A perda de material pode atingir pavimento, muro, imóvel ou fundação.","pesoRisco":0.6},{"id":"erosao_ativa","texto":"Erosão ativa ou solapamento","descricao":"A água remove apoio e pode provocar ruptura ou desmoronamento.","pesoRisco":1}]},{"id":"drenagem_q5","texto":"Há assoreamento, lixo ou material carregado pela água?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_material","texto":"Sem material acumulado","descricao":"Seção e entorno livres de material que reduza o fluxo.","pesoRisco":0},{"id":"material_pontual","texto":"Material pontual","descricao":"Há acúmulo pequeno e removível com limpeza de rotina.","pesoRisco":0.3},{"id":"assoreamento_relevante","texto":"Assoreamento relevante","descricao":"Sedimentos ou resíduos reduzem significativamente a seção de passagem.","pesoRisco":0.6},{"id":"bloqueio_por_material","texto":"Bloqueio por material ou detritos","descricao":"Galhos, resíduos ou sedimentos impedem o escoamento.","pesoRisco":1}]},{"id":"drenagem_q6","texto":"Como está a condição estrutural do dispositivo?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"estrutura_integra","texto":"Estrutura íntegra","descricao":"Sem trincas, deslocamentos ou deformações relevantes.","pesoRisco":0},{"id":"fissura_desgaste","texto":"Fissura ou desgaste superficial","descricao":"Dano localizado sem perda aparente de suporte.","pesoRisco":0.3},{"id":"deslocamento_parcial","texto":"Deslocamento, trinca ou deformação relevante","descricao":"Há redução do funcionamento ou risco de agravamento.","pesoRisco":0.6},{"id":"colapso_estrutural","texto":"Colapso ou perda de suporte","descricao":"Parte do dispositivo está rompida, deslocada ou sem condição de uso.","pesoRisco":1}]},{"id":"drenagem_q7","texto":"Qual o efeito sobre a via ou o terreno?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_efeito","texto":"Sem efeito relevante","descricao":"Via e terreno permanecem estáveis.","pesoRisco":0},{"id":"acumulo_local","texto":"Acúmulo localizado de água","descricao":"Há poça ou umidade sem perda de circulação.","pesoRisco":0.3},{"id":"dano_pavimento","texto":"Dano no pavimento ou acostamento","descricao":"Há buraco, abatimento, erosão ou redução da circulação.","pesoRisco":0.6},{"id":"ruptura_via","texto":"Ruptura, desmoronamento ou via ameaçada","descricao":"A circulação está insegura ou a via pode romper.","pesoRisco":1}]},{"id":"drenagem_foto_entrada_saida","texto":"Foto da entrada, saída ou ponto de dano","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]}]},{"id":"drenagem_exposicao","titulo":"Exposição e providências","instrucao":"Avalie os alvos próximos e encaminhe a limpeza, manutenção, sinalização ou interdição compatível com o risco.","perguntas":[{"id":"drenagem_q8","texto":"Há imóveis, pessoas ou equipamento público exposto?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_alvo","texto":"Sem alvo próximo","descricao":"Não há pessoas, imóveis ou equipamentos diretamente ameaçados.","pesoRisco":0},{"id":"alvo_eventual","texto":"Alvo eventual","descricao":"Há circulação ou bem isolado com possibilidade limitada de dano.","pesoRisco":0.3},{"id":"imovel_ou_via","texto":"Imóvel ou via exposta","descricao":"O mau funcionamento pode atingir ocupação ou circulação frequente.","pesoRisco":0.6},{"id":"infraestrutura_essencial","texto":"Infraestrutura essencial ou múltiplos alvos","descricao":"A ameaça atinge acesso principal, serviço público ou várias ocupações.","pesoRisco":1}]},{"id":"drenagem_q9","texto":"Como está a possibilidade de manutenção e acesso?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"acesso_facil","texto":"Acesso fácil","descricao":"Equipe consegue acessar o ponto com segurança.","pesoRisco":0},{"id":"acesso_condicionado","texto":"Acesso condicionado","descricao":"É necessária sinalização ou equipamento simples para manutenção.","pesoRisco":0.3},{"id":"acesso_dificil","texto":"Acesso difícil","descricao":"Talude, água, tráfego ou instabilidade dificultam o serviço.","pesoRisco":0.6},{"id":"acesso_inseguro","texto":"Acesso inseguro","descricao":"A entrada apresenta risco de soterramento, queda, afogamento ou colapso.","pesoRisco":1}]},{"id":"drenagem_q10","texto":"Qual providência deve ser encaminhada?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"manutencao_rotina","texto":"Manutenção de rotina","descricao":"Limpeza ou ajuste programável sem restrição imediata.","pesoRisco":0},{"id":"limpeza_prioritaria","texto":"Limpeza prioritária","descricao":"Remover material e acompanhar antes de novos eventos de chuva.","pesoRisco":0.3},{"id":"intervencao_urgente","texto":"Intervenção urgente","descricao":"Executar reparo, proteção de margem, sinalização ou desvio.","pesoRisco":0.6},{"id":"isolar_via","texto":"Isolar via ou área","descricao":"Impedir circulação e acionar equipe responsável por emergência.","pesoRisco":1}]},{"id":"drenagem_acao_imediata","texto":"Descreva a providência ou encaminhamento realizado","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: ponto sinalizado, equipe de obras acionada e rota alternativa indicada.","mostrarQuando":{"perguntaId":"drenagem_q10","respostaIds":["intervencao_urgente","isolar_via"]},"opcoes":[]},{"id":"drenagem_observacoes","texto":"Observações técnicas adicionais","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Registre dimensões, referências, histórico e recomendações.","opcoes":[]}]}]}'::jsonb),
  ('avaliacao_arvore_cbmmg_v1', 'Avaliação de Árvore de Risco - CBMMG', 'Avaliação de árvore de risco conforme ITO nº 06 do CBMMG, Apêndice B, Quadro 2.', '{"id":"avaliacao_arvore_cbmmg_v1","titulo":"Avaliação de Árvore de Risco - CBMMG","versao":1,"ativo":true,"featureCode":"inspection_arv","tipoCalculo":"soma_total","descricao":"Avaliação de árvore de risco conforme ITO nº 06 do CBMMG, Apêndice B, Quadro 2.","metodologia":{"id":"cbmmg_ito06_quadro2","versao":"1.0","titulo":"Quadro de Avaliação de Árvore de Risco","fonte":"Corpo de Bombeiros Militar de Minas Gerais - ITO nº 06 - Vistoria, Poda e Corte de Árvores - Apêndice B - Quadro 2; adaptado de Pokorny (2003).","escala":{"min":0,"max":10,"teto":10},"faixasResultado":[{"max":8,"codigo":"nao_iminente","label":"NÃO IMINENTE","nivelCompatibilidade":"r1","cor":"#10B981","conduta":"Registrar medidas preventivas, orientar o responsável e programar acompanhamento conforme avaliação técnica."},{"max":10,"codigo":"risco_iminente","label":"RISCO IMINENTE","nivelCompatibilidade":"r4","cor":"#DC2626","conduta":"Intervenção para eliminação do risco por meio do corte da parte perigosa. A decisão de não intervir deve ser justificada no REDS."}]},"classificacao":{"limites":[{"max":8,"nivel":"r1","label":"NÃO IMINENTE","cor":"verde"},{"max":10,"nivel":"r4","label":"RISCO IMINENTE","cor":"vermelho"}]},"fases":[{"id":"arv_identificacao","titulo":"Identificação e referência de campo","instrucao":"Registre a árvore avaliada. A altura estimada define o raio de referência dos alvos: 1,5 vezes a altura da árvore.","perguntas":[{"id":"arv_foto_geral","texto":"Foto geral da árvore e da área de projeção","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]},{"id":"arv_altura_m","texto":"Altura estimada da árvore","descricao":"Informe a altura aproximada em metros. O app calculará o raio de referência dos alvos.","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"m","valorMinimo":0.1,"obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: 12,5","calculoDerivado":"raio_alvo_1_5x","opcoes":[]},{"id":"arv_especie_aparente","texto":"Espécie aparente (opcional)","descricao":"Preencha apenas quando houver identificação visual segura.","tipo":"texto","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: Sibipiruna","opcoes":[]}]},{"id":"arv_item_1","titulo":"Item 1 - Avaliação dos alvos","instrucao":"Considere todos os alvos dentro do perímetro cujo raio é 1,5 vezes a altura da árvore, a partir do tronco. Tome a maior pontuação entre as situações apresentadas.","perguntas":[{"id":"arv_item1_alvo","texto":"Qual é o alvo de maior exposição dentro da zona de risco?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"pessoas_frequente","texto":"Pessoas - ocupação frequente","descricao":"Há risco a pessoas em residência, escola, comércio ou circulação contínua.","pesoRisco":3},{"id":"pessoas_ocasional","texto":"Pessoas - ocupação ocasional","descricao":"Há risco eventual a pessoas, com ocupação ocasional.","pesoRisco":2},{"id":"bens_propriedades","texto":"Bens ou propriedades","descricao":"Não há risco a pessoas; há risco a bens ou propriedades.","pesoRisco":1},{"id":"nenhum_alvo","texto":"Nenhum alvo exposto","descricao":"Não há risco a pessoas, bens ou propriedades.","pesoRisco":0}]},{"id":"arv_medida_mitigadora_status","texto":"Foi possível aplicar medida mitigadora ao alvo?","descricao":"Sempre que viável, remova o bem da zona de risco ou restrinja o acesso de pessoas.","tipo":"multipla_escolha","obrigatoria":true,"auxiliarCalculo":true,"opcoes":[{"id":"aplicada","texto":"Sim, medida aplicada","pesoRisco":0},{"id":"nao_aplicada","texto":"Não aplicada","pesoRisco":0},{"id":"nao_viavel","texto":"Não foi viável aplicar","pesoRisco":0}]},{"id":"arv_medida_mitigadora_descricao","texto":"Medida mitigadora ou justificativa","descricao":"Descreva a medida aplicada. Se nenhuma medida foi aplicada, justifique tecnicamente.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: área isolada e acesso de pedestres restringido no raio estimado.","opcoes":[]}]},{"id":"arv_item_2","titulo":"Item 2 - Avaliação da árvore, tronco e galhos","instrucao":"Avalie o risco de queda de toda a árvore ou da parte específica. Selecione somente um grau: o mais elevado compatível com o defeito determinante. Os critérios e graus inferiores não são somados.","perguntas":[{"id":"arv_item2_severidade","texto":"Qual é o grau de risco mais elevado observado?","descricao":"Escolha apenas um grau para o defeito determinante da árvore, do tronco, dos galhos ou das raízes.","tipo":"cards","layout":"lista","obrigatoria":true,"opcoes":[{"id":"extremamente_alto","texto":"Grau extremamente alto - 4 pontos","descricao":"Tronco degradado ou cavidade excedendo limites de segurança com rachadura severa; tronco ou galho rachado ao meio; defeitos afetando >=40% da circunferência com degradação extensa ou fissuras; união fraca com fissura e degradação; inclinação com rachaduras/elevação recente do solo e degradação extensa; galhos mortos quebrados/dependurados ou rachados; árvore morta com outros defeitos; obstrução física inviável ao tráfego.","pesoRisco":4},{"id":"alto","texto":"Grau alto - 3 pontos","descricao":"Tronco degradado ou cavidade >30% da circunferência ou no limite de segurança; rachaduras em contato com o solo ou associadas; defeitos >40%; copa quebrada/danificada acima dos limites; união fraca com rachaduras ou degradação; acinturamento de raízes >=40%; danos à raiz >=40% dentro do RCR; inclinação com fissuras/elevação recente, rachaduras ou degradação; árvore morta sem outros defeitos significativos.","pesoRisco":3},{"id":"moderado","texto":"Grau moderado - 2 pontos","descricao":"Tronco pouco degradado ou cavidade dentro dos limites de segurança; rachaduras sem degradação extensa; defeitos afetando 30% a 40%; copa danificada dentro dos limites; união fraca em galhos grandes ou troncos codominantes; acinturamento <40%; danos à raiz <40% dentro do RCR.","pesoRisco":2},{"id":"baixo","texto":"Grau baixo - 1 ponto","descricao":"Perda de vigor menos intensa da copa ou galhos; pequenos defeitos, ferimentos ou cancros.","pesoRisco":1}]},{"id":"arv_parte_defeituosa","texto":"Parte específica avaliada","descricao":"Identifique tronco, galho, raiz, copa ou outra parte que contém o defeito determinante.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: tronco principal, região da cavidade.","opcoes":[]},{"id":"arv_defeito_determinante","texto":"Descrição técnica do defeito determinante","descricao":"Registre localização, natureza, extensão aparente e sinais associados ao defeito mais severo.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"placeholder":"Ex.: cavidade externa estimada em 35% da circunferência e rachadura longitudinal severa.","opcoes":[]},{"id":"arv_foto_defeito","texto":"Foto do defeito determinante","tipo":"foto","obrigatoria":false,"auxiliarCalculo":true,"opcoes":[]}]},{"id":"arv_item_3","titulo":"Item 3 - Maior diâmetro da parte defeituosa","instrucao":"Considere a parte específica que apresenta o defeito mais grave indicado no Item 2, e não necessariamente o maior diâmetro da árvore.","perguntas":[{"id":"arv_item3_diametro_faixa","texto":"Qual é o maior diâmetro da parte defeituosa?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"maior_51","texto":"Maior que 51 cm","descricao":"Maior potencial de dano em caso de falha.","pesoRisco":3},{"id":"entre_10_51","texto":"De 10 a 51 cm","descricao":"Faixa intermediária de potencial de dano.","pesoRisco":2},{"id":"menor_10","texto":"Menor que 10 cm","descricao":"Parte defeituosa de menor diâmetro.","pesoRisco":1}]},{"id":"arv_diametro_exato_cm","texto":"Diâmetro medido (opcional)","descricao":"Informe o valor em centímetros quando houver medição ou estimativa confiável.","tipo":"texto","tipoEntrada":"numero_decimal","unidade":"cm","valorMinimo":0.1,"validarComPergunta":"arv_item3_diametro_faixa","obrigatoria":false,"auxiliarCalculo":true,"placeholder":"Ex.: 42","opcoes":[]}]},{"id":"arv_item_4","titulo":"Item 4 - Outros fatores de risco presentes","instrucao":"A critério do avaliador, acrescente 0, 1 ou 2 pontos para defeitos não contemplados no quadro.","perguntas":[{"id":"arv_item4_outros_fatores","texto":"Existem outros fatores de risco não contemplados?","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"sem_acrescimo","texto":"Sem acréscimo","descricao":"Nenhum fator adicional identificado.","pesoRisco":0},{"id":"acrescimo_1","texto":"Acrescentar 1 ponto","descricao":"Fator adicional relevante.","pesoRisco":1},{"id":"acrescimo_2","texto":"Acrescentar 2 pontos","descricao":"Fator adicional de forte influência.","pesoRisco":2}]},{"id":"arv_outros_fatores_descricao","texto":"Descrição do fator adicional","descricao":"Explique o fator não contemplado e sua influência no risco final.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"arv_item4_outros_fatores","respostaIds":["acrescimo_1","acrescimo_2"]},"placeholder":"Descreva o fator adicional observado.","opcoes":[]}]},{"id":"arv_conduta","titulo":"Conduta em risco iminente","instrucao":"O risco é iminente quando o total é igual ou superior a 9 pontos. Registre a decisão operacional.","perguntas":[{"id":"arv_decisao_operacional","texto":"Qual será a decisão operacional?","tipo":"cards","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuandoPontuacaoMinima":9,"opcoes":[{"id":"intervir","texto":"Intervir","descricao":"Encaminhar intervenção para eliminação do risco da parte perigosa.","pesoRisco":0},{"id":"nao_intervir","texto":"Não intervir","descricao":"A decisão deve ser tecnicamente justificada no REDS.","pesoRisco":0}]},{"id":"arv_conduta_recomendada","texto":"Conduta recomendada","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"arv_decisao_operacional","respostaIds":["intervir"]},"mostrarQuandoPontuacaoMinima":9,"placeholder":"Ex.: corte controlado da parte perigosa por equipe habilitada.","opcoes":[]},{"id":"arv_nao_intervencao_justificativa","texto":"Justificativa técnica para não intervir","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"arv_decisao_operacional","respostaIds":["nao_intervir"]},"mostrarQuandoPontuacaoMinima":9,"placeholder":"Descreva os fundamentos técnicos da decisão.","opcoes":[]},{"id":"arv_reds_numero","texto":"Número do REDS","descricao":"Aceita identificação alfanumérica conforme o registro operacional.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"arv_decisao_operacional","respostaIds":["nao_intervir"]},"mostrarQuandoPontuacaoMinima":9,"placeholder":"Informe o número do REDS.","opcoes":[]}]}]}'::jsonb),
  ('vistoria_deslizamento_v3', 'Vistoria de Risco de Deslizamento', 'Formulário de campo em escala padronizada de 0,0 a 10,0 para avaliação de risco de deslizamento em encostas e taludes.', '{"id":"vistoria_deslizamento_v3","titulo":"Vistoria de Risco de Deslizamento","versao":3,"ativo":true,"tipoCalculo":"soma_total","descricao":"Formulário de campo em escala padronizada de 0,0 a 10,0 para avaliação de risco de deslizamento em encostas e taludes.","classificacao":{"limites":[{"max":2,"nivel":"r1","label":"R1 — BAIXO — Condição controlada","cor":"verde"},{"max":3.9,"nivel":"r2","label":"R2 — MÉDIO — Monitoramento e medidas preventivas","cor":"amarelo"},{"max":6.9,"nivel":"r3","label":"R3 — ALTO — Intervenção técnica urgente necessária","cor":"laranja"},{"max":10,"nivel":"r4","label":"R4 — CRÍTICO — Risco máximo, interdição/evacuação quando aplicável","cor":"vermelho"}]},"fases":[{"id":"fase_deslizamento","titulo":"Vistoria de Campo — Risco de Deslizamento","instrucao":"Preencha todos os campos observando as condições atuais do local. A pontuação total determina o nível de risco.","perguntas":[{"id":"desl2_foto_geral","texto":"Foto geral do local / encosta","tipo":"foto","obrigatoria":false,"opcoes":[]},{"id":"desl2_q1","texto":"Caracterização do local","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"inexistente","texto":"Inexistente","descricao":"Item inexistente ou nao aplicavel ao local vistoriado","pesoRisco":0},{"id":"q1_a","texto":"Encosta Natural","descricao":"Terreno sem intervenção humana","svgKey":"desl2_q1_a","pesoRisco":0},{"id":"q1_b","texto":"Aterro","descricao":"Terreno com material depositado artificialmente","svgKey":"desl2_q1_b","pesoRisco":1}]},{"id":"desl2_q2","texto":"Inclinação da encosta","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"inexistente","texto":"Inexistente","descricao":"Item inexistente ou nao aplicavel ao local vistoriado","pesoRisco":0},{"id":"q2_a","texto":"≤ 10°","descricao":"Inclinação suave","svgKey":"desl2_q2_a","pesoRisco":0},{"id":"q2_b","texto":"~17°","descricao":"Inclinação moderada","svgKey":"desl2_q2_b","pesoRisco":0.3},{"id":"q2_c","texto":"~30°","descricao":"Inclinação acentuada","svgKey":"desl2_q2_c","pesoRisco":0.6},{"id":"q2_d","texto":"~60°","descricao":"Inclinação muito acentuada","svgKey":"desl2_q2_d","pesoRisco":0.8},{"id":"q2_e","texto":"≥90° (vertical)","descricao":"Parede vertical","svgKey":"desl2_q2_e","pesoRisco":1},{"id":"q2_f","texto":"Inclinação negativa / talude solapado","descricao":"Face verticalizada ou com base erodida/solapada, comida por baixo, em balanço ou com perda de apoio visível","svgKey":"desl2_q2_e","pesoRisco":1}]},{"id":"desl2_q2_exposicao_altura_distancia","texto":"Classificação do risco considerando altura do talude e distância até o alvo vulnerável","tipo":"multipla_escolha","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"desl2_q2","respostaIds":["q2_e","q2_f"]},"opcoes":[{"id":"baixo","texto":"Baixo","descricao":"Distância bem maior que a altura do talude e sem alvo diretamente atingível","pesoRisco":0},{"id":"medio","texto":"Médio","descricao":"Distância moderada, com possibilidade limitada de impacto","pesoRisco":0},{"id":"alto","texto":"Alto","descricao":"Alvo próximo, dentro da zona provável de alcance","pesoRisco":0},{"id":"muito_alto","texto":"Muito alto","descricao":"Alvo muito próximo ou imediato, especialmente com base solapada, massa em balanço, trincas, erosão ativa ou sinais de queda iminente","pesoRisco":0},{"id":"nao_estimado","texto":"Não foi possível estimar","descricao":"Manter postura conservadora quando altura, distância ou alcance provável não puderem ser estimados","pesoRisco":0}]},{"id":"desl2_q2_justificativa_tecnica","texto":"Justificativa técnica da classificação altura x distância","descricao":"Informe altura aproximada, distância até o alvo vulnerável e sinais observados, como base solapada, crista em balanço, trincas, erosão, material desprendido ou queda recente.","placeholder":"Ex.: talude com cerca de 10 m de altura, imóvel a 8 m da base, base solapada e trincas na crista.","tipo":"texto","obrigatoria":true,"auxiliarCalculo":true,"mostrarQuando":{"perguntaId":"desl2_q2","respostaIds":["q2_e","q2_f"]},"opcoes":[]},{"id":"desl2_q3","texto":"Drenagem superficial da encosta","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"inexistente","texto":"Inexistente","descricao":"Item inexistente ou não aplicável ao local vistoriado","pesoRisco":0},{"id":"q3_a","texto":"Satisfatória","descricao":"Drenagem funcional, sem acúmulo de água","svgKey":"desl2_q3_a","pesoRisco":0},{"id":"q3_b","texto":"Precária","descricao":"Drenagem deficiente, alguns pontos de acúmulo","svgKey":"desl2_q3_b","pesoRisco":0.6},{"id":"q3_c","texto":"Sem drenagem","descricao":"Ausência de drenagem superficial; água acumula livremente","svgKey":"desl2_q3_c","pesoRisco":1}]},{"id":"desl2_q4","texto":"Vegetação no talude","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"inexistente","texto":"Inexistente","descricao":"Item inexistente ou nao aplicavel ao local vistoriado","pesoRisco":0},{"id":"q4_a","texto":"Presença de Árvores","descricao":"Vegetação arbórea — raízes profundas estabilizando o solo","svgKey":"desl2_q4_a","pesoRisco":0},{"id":"q4_b","texto":"Vegetação Rasteira","descricao":"Capim ou arbustos — proteção superficial limitada","svgKey":"desl2_q4_b","pesoRisco":0.3},{"id":"q4_c","texto":"Área Desmatada","descricao":"Solo exposto sem cobertura vegetal","svgKey":"desl2_q4_c","pesoRisco":1},{"id":"q4_d","texto":"Área de Cultivo","descricao":"Cultivo agrícola — solo revolvido e pouco protegido","svgKey":"desl2_q4_d","pesoRisco":1}]},{"id":"desl2_q5","texto":"Trincas no solo ou estruturas da encosta","tipo":"cards","obrigatoria":true,"opcoes":[{"id":"inexistente","texto":"Inexistente","descricao":"Item inexistente ou nao aplicavel ao local vistoriado","pesoRisco":0},{"id":"q5_a","texto":"Não","descricao":"Sem trincas visíveis","svgKey":"desl2_q5_a","pesoRisco":0},{"id":"q5_b",